    <article className={variant === 'wide' ? 'card card--wide' : 'card card--compact'}>
      <img src={exhibition.image} alt="" />
      <div>
        <h3>{exhibition.title}</h3>
        {variant === 'wide' && <p>{exhibition.summary}</p>}
      </div>
    </article>
  );
}
