A pick-list slice is reported to occasionally lose picked-quantity updates when two scans happen in very quick succession. Diagnose using the purity and draft rules from this experience.

```ts
let lastDraftLine: PickLine | null = null;

const pickListSlice = createSlice({
  name: 'pickList',
  initialState,
  reducers: {
    itemPicked(state, action: PayloadAction<{ sku: string; qty: number }>) {
      const line = state.lines[action.payload.sku];
      if (!line) return;
      lastDraftLine = line;                    // kept "for convenience"
      line.pickedQty += action.payload.qty;
    },
    itemPickedAgain(state, action: PayloadAction<{ qty: number }>) {
      if (lastDraftLine) {
        lastDraftLine.pickedQty += action.payload.qty;   // crashes here
      }
    },
  },
});
```

